// capability interface this plugin ships). The sdk.MetadataSourcePlugin adapter
// forwards the four unary RPCs here. Mirrors plugins/tv-parser/parser.go.
var _ sdk.MetadataSource = (*parserImpl)(nil)

// parserImpl is the server-side MetadataSource capability for serial-parser.
// It is STATELESS between RPCs: every output is a pure function of the request.
// The plugin self-selects PER DOCUMENT at Match (serials-library D5): a SERIES
// document (parsed carries the serial-record marker) parses the raw directory
// facts into a cleaned display title + season; an EPISODE document applies iff
// its filename carries an SxxExx token and parses the episode numbers. Anything
// else is applies=false — a skipped stage, not an error. Merge writes ONLY
// sources["serial-parser"]; the core stamps _provenance/_view authoritatively
// (INV-namespace-write). A local parser: BuildRequest is a nop (no fetch).
type parserImpl struct{}

// Marker fact names the serial-scanner stamps into parsed (design.md
// §Interfaces §1-2). Read here as plain facts — the plugin never imports core.
const (
	factSerialRecord       = "serial_record"
	factDirNameRaw         = "dir_name_raw"
	factSeriesRelativePath = "series_relative_path"
	factRelativePath       = "relative_path"
)

// Match self-selects per document. A serial-record document parses the raw
// directory name (dir_name_raw, falling back to the series path); an episode
// document applies iff its filename carries an SxxExx token. Non-applying
// documents are skipped stages recorded by the core (not errors).
func (*parserImpl) Match(_ context.Context, req *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	f := req.GetItem().GetParsed().GetFields()
	if f[factSerialRecord].GetBoolValue() {
		raw := f[factDirNameRaw].GetStringValue()
		if raw == "" {
			raw = f[factSeriesRelativePath].GetStringValue()
		}
		if raw == "" {
			return &metadatav1.MatchResult{Applies: false, Reason: "serial record without directory facts"}, nil
		}
		title, season, hasSeason := parseSeriesDir(raw)
		q := map[string]any{
			"title":        title,
			"dir_name_raw": raw,
		}
		confidence := 0.6
		if hasSeason {
			q["season"] = int64(season)
			confidence = 1.0
		}
		query, _ := structpb.NewStruct(q)
		return &metadatav1.MatchResult{
			Applies:    true,
			Query:      query, // the parsed directory facts become the chain's query
			Confidence: confidence,
			Reason:     "serial-record directory facts",
		}, nil
	}

	rel := parsedString(f, factRelativePath)
	season, episode, episodeEnd, ok := parseEpisodeFilename(rel)
	if !ok {
		return &metadatav1.MatchResult{Applies: false, Reason: "no SxxExx token in filename"}, nil
	}
	q := map[string]any{
		"season":  int64(season),
		"episode": int64(episode),
	}
	if episodeEnd > 0 {
		q["episode_end"] = int64(episodeEnd)
	}
	query, _ := structpb.NewStruct(q)
	return &metadatav1.MatchResult{
		Applies:    true,
		Query:      query,
		Confidence: 1.0,
		Reason:     "episode filename SxxExx token",
	}, nil
}

